/* ===== V124: خلط ثاني — طبخ التمن (المقادير لكل 2 كيلو تمن) ===== */
const RMIX_STD=[
  {name:'معجون انتوسنا',amt:4,unit:'ملعقة كبيرة',sup:'معجون انتوسنا',g:20},
  {name:'زيت',amt:0.5,unit:'بطل',sup:'زيت',g:2500},
  {name:'ماجي',amt:3,unit:'قطعة'},
  {name:'فلفل أسود مطحون',amt:1.5,unit:'ملعقة'},
  {name:'بهارات برياني',amt:1.5,unit:'ملعقة'},
  {name:'ثوم وبصل مطحون',amt:0.5,unit:'ملعقة'},
  {name:'ملح',amt:50,unit:'غرام'}
];
function rmixItems(){ if(!Array.isArray(settings.riceMix)||!settings.riceMix.length) settings.riceMix=JSON.parse(JSON.stringify(RMIX_STD)); return settings.riceMix }
const nfmt=v=>{ v=Math.round(v*100)/100; const w=Math.floor(v), f=Math.round((v-w)*100)/100; const fr={0.25:'ربع',0.5:'نص',0.75:'ثلاث أرباع'}[f]; return fr?(w?fmt(w)+' و'+fr:fr):fmt(v) };
function rmixPreview(){
  const kg=Math.max(0,parseFloat(document.getElementById('rmKg').value)||0), k=kg/2, box=document.getElementById('rmPrev');
  box.innerHTML=`<table class="mix-t"><thead><tr><th>المادة</th><th>لكل 2 كيلو</th><th>لـ ${nfmt(kg)} كيلو تمن</th></tr></thead><tbody>`+
    rmixItems().map(it=>`<tr><td>${esc(it.name)}</td><td>${nfmt(it.amt)} ${esc(it.unit)}</td><td><b>${nfmt(it.amt*k)} ${esc(it.unit)}</b></td></tr>`).join('')+`</tbody></table>`;
  const L=(settings.riceCooks||[]).slice(-5).reverse();
  document.getElementById('rmLog').innerHTML=L.length?'<div class="hint" style="margin-top:12px">آخر الطبخات</div>'+L.map(c=>`<div class="trow"><span>${new Date(c.ts).toLocaleDateString('ar-IQ-u-nu-latn',{weekday:'short',day:'numeric',month:'numeric'})}، ${new Date(c.ts).toLocaleTimeString('ar-IQ-u-nu-latn',{hour:'numeric',minute:'2-digit'})}</span><span>${nfmt(c.kg)} كيلو</span></div>`).join(''):'';
}
function rmixEdit(){
  const ov=document.createElement('div'); ov.className='ov'; let list=rmixItems().map(x=>Object.assign({},x));
  const draw=()=>{ ov.innerHTML=`<div class="dlg" role="dialog" aria-modal="true"><div class="dlg-t">مقادير طبخ التمن (لكل 2 كيلو)</div>
    <div class="bw-list">${list.map((n,i)=>`<div class="fcount-row"><input data-n="${i}" value="${esc(n.name)}" aria-label="المادة"><input data-a="${i}" type="number" inputmode="decimal" step="0.25" value="${n.amt}" style="max-width:80px" aria-label="الكمية"><input data-u="${i}" value="${esc(n.unit)}" style="max-width:110px" aria-label="الوحدة"><button class="btn-ghost" data-del="${i}" type="button">احذف</button></div>`).join('')}</div>
    <div class="fcount-row" style="margin-top:10px"><input id="rmN" placeholder="مادة جديدة"><input id="rmA" type="number" step="0.25" placeholder="الكمية" style="max-width:80px"><input id="rmU" placeholder="الوحدة" style="max-width:110px"><button class="btn-dark" id="rmAdd" type="button">ضيف</button></div>
    <div class="dlg-act"><button class="btn-main" id="rmSave">احفظ</button><button class="btn-ghost" id="rmX">إلغاء</button></div></div>`;
    const rd=()=>{ ov.querySelectorAll('[data-n]').forEach(x=>{ const i=+x.dataset.n; list[i].name=x.value.trim(); list[i].amt=Math.max(0,parseFloat(ov.querySelector('[data-a="'+i+'"]').value)||0); list[i].unit=ov.querySelector('[data-u="'+i+'"]').value.trim() }) };
    ov.querySelectorAll('[data-del]').forEach(b=>b.addEventListener('click',()=>{ rd(); list.splice(+b.dataset.del,1); draw() }));
    ov.querySelector('#rmAdd').addEventListener('click',()=>{ rd(); const n=ov.querySelector('#rmN').value.trim(); if(!n){ toast('اكتب اسم المادة'); return } list.push({name:n,amt:parseFloat(ov.querySelector('#rmA').value)||0,unit:ov.querySelector('#rmU').value.trim()}); draw() });
    ov.querySelector('#rmX').addEventListener('click',()=>ov.remove());
    ov.querySelector('#rmSave').addEventListener('click',()=>{ rd(); settings.riceMix=list.filter(x=>x.name); saveAll(); ov.remove(); rmixPreview(); toast('انحفظت المقادير') });
  };
  draw(); document.body.appendChild(ov);
}
document.getElementById('rmKg').addEventListener('input',rmixPreview);
document.querySelectorAll('#rmQuick button').forEach(b=>b.addEventListener('click',()=>{ document.getElementById('rmKg').value=b.dataset.n; rmixPreview() }));
document.getElementById('rmEdit').addEventListener('click',rmixEdit);
document.getElementById('rmDone').addEventListener('click',()=>{
  const kg=parseFloat(document.getElementById('rmKg').value)||0; if(!(kg>0)){ toast('اكتب كم كيلو تمن'); return }
  uiYes('تسجل طبخة '+nfmt(kg)+' كيلو تمن؟ الزيت والمعجون ينقصن من المخزن.',()=>{
    const S=supAll(), k=kg/2;
    rmixItems().forEach(it=>{ if(it.sup&&it.g&&S[it.sup]) S[it.sup].used=Math.round(((S[it.sup].used||0)+it.amt*k*it.g)*10)/10 });
    settings.riceCooks=(settings.riceCooks||[]).concat([{ts:Date.now(),kg}]).slice(-300);
    saveAll(); try{ supRender() }catch(_){} rmixPreview(); toast('انسجلت الطبخة');
  });
});
setTimeout(()=>{ try{ rmixPreview() }catch(_){} },0);

const SAFI_VER='V124';
  <div class="card mixcard" id="riceMixCard">
    <h3>طبخ التمن</h3>
    <div class="two">
      <div><label for="rmKg">كم كيلو تمن تطبخ؟</label><input id="rmKg" type="number" inputmode="decimal" min="0.5" step="0.5" value="2"></div>
      <div class="mix-q" id="rmQuick"><button data-n="2">2</button><button data-n="4">4</button><button data-n="6">6</button><button data-n="10">10</button></div>
    </div>
    <div class="mix-prev" id="rmPrev"></div>
    <button class="btn-main" id="rmDone" type="button">سجّل الطبخة</button>
    <button class="btn-sm" id="rmEdit" type="button" style="margin-top:10px">عدّل المقادير</button>
    <div id="rmLog"></div>
  </div>
